const data = $input.item.json.collected_data || {};
const selections = data.selections || [];

// 1. Define Analysis Modules
const allOptions = [
  { text: "🚀 Momentum (RSI/Stoch)", id: "MOMENTUM" },
  { text: "📈 Trend (MA/Levels)", id: "TREND" },
  { text: "⚡ Volatility (Bollinger)", id: "VOLATILITY" },
  { text: "🖼️ Chart Visuals", id: "CHARTS" }
];

// 2. Filter remaining options
const remainingOptions = allOptions.filter(opt => !selections.includes(opt.id));

const rows = [];

// 3. Build Module Buttons
remainingOptions.forEach(opt => {
  rows.push([{ text: opt.text, callback_data: opt.id }]);
});

// 4. Add Execute Button if items selected
if (selections.length > 0) {
  rows.push([{ text: "▶️ Execute Analysis", callback_data: "PROCEED_ANALYSIS" }]);
}

// 5. Add Cancel Button (Unified Style)
rows.push([{ text: "🔙 Cancel Operation", callback_data: "menu2" }]);

// 6. Format Text for Display
const selectionText = selections.length > 0 
  ? selections.join(' + ') 
  : "Pending Selection...";

// 7. Output payload
return { 
  json: { 
    reply_markup: { inline_keyboard: rows }, 
    selectionText: selectionText 
  } 
};

const items = $input.all();
const result = {};

for (let i = 0; i < 4; i++) {
  if (items[i]) {
    const content = items[i].json.document.pageContent;
    const tokenMatch = content.match(/token=(\d+)/);
    const token = tokenMatch ? tokenMatch[1] : 'ignore';
    const symbolMatch = content.match(/symbol=([^,]+)/);
    const symbol = symbolMatch ? symbolMatch[1] : 'UNKNOWN';
    const namePart = content.split('name=')[1] || '';
    const name = namePart.split(', exchange')[0].trim();

    result[`text_${i + 1}`] = `${symbol} (${name})`;
    result[`callback_${i + 1}`] = token;
  } else {
    result[`text_${i + 1}`] = ' ';
    result[`callback_${i + 1}`] = 'ignore';
  }
}
return { json: result };

