// 🧠 CENTRAL BRAIN: MASTER CONTROLLER
const session = $input.item.json;
const state = session.current_state || 'IDLE';

const trigger = $('Telegram Trigger').item.json;
const callback = trigger.callback_query ? trigger.callback_query.data : null;
const text = trigger.message ? trigger.message.text : null;

// --- 1. GLOBAL COMMANDS ---
if (text === '/start' || callback === 'start_bot') {
  return { json: { route: 'SHOW_MENU' } };
}
if (callback === 'close') {
  return { json: { route: 'END_SESSION' } };
}

// --- 2. SAFE NAVIGATION (MAIN MENU) ---
// 'menu' = Safe exit (List, Help) -> Go straight to menu
if (callback === 'menu') { return { json: { route: 'SHOW_MENU' } }; }

// 'menu2' = Unsafe exit (Create, Update) -> Ask for confirmation
if (callback === 'menu2') { return { json: { route: 'ASK_CONFIRM_MENU' } }; }

// Confirmation Responses
if (callback === 'confirm_yes') { return { json: { route: 'SHOW_MENU' } }; }
if (callback === 'confirm_no') { return { json: { route: 'DELETE_WARNING' } }; }

// --- 3. MAIN MENU SELECTIONS ---
if (state === 'IDLE' && callback) {
  if (callback === 'list') return { json: { route: 'EXECUTE_LIST' } };
  if (callback === 'create') return { json: { route: 'START_CREATE' } };
  if (callback === 'update') return { json: { route: 'START_UPDATE' } };
  if (callback === 'delete') return { json: { route: 'START_DELETE' } };
  if (callback === 'analyze') return { json: { route: 'START_ANALYZE' } };
  if (callback === 'help') return { json: { route: 'SHOW_HELP' } };
}

// --- NEW: RE-SEARCH LOGIC ---
if (callback === 'research_stock') {
  // Check the current state to know where to send them back
  if (state.includes('ANALYZE')) return { json: { route: 'START_ANALYZE' } };
  if (state.includes('CREATE')) return { json: { route: 'START_CREATE' } };
  if (state.includes('UPDATE')) return { json: { route: 'START_UPDATE' } };

  // Fallback
  return { json: { route: 'SHOW_MENU' } };
}

// --- 4. CREATE FLOW ---
if (state === 'CREATE_AWAITING_STOCK') {
  if (text) return { json: { route: 'SEARCH_STOCK_CREATE', query: text } };
  if (callback) return { json: { route: 'SAVE_TOKEN_ASK_PRICE', token: callback } };
}
if (state === 'CREATE_AWAITING_PRICE' && text) {
  return { json: { route: 'SAVE_PRICE_ASK_COND', price: text } };
}
if (state === 'CREATE_AWAITING_CONDITION' && callback) {
  return { json: { route: 'EXECUTE_CREATE', condition: callback } };
}

// --- 5. UPDATE FLOW (Full Loop) ---
if (state === 'UPDATE_AWAITING_STOCK') {
  if (text) return { json: { route: 'SEARCH_STOCK_UPDATE', query: text } };
  if (callback) return { json: { route: 'SAVE_TOKEN_ASK_PRICE_UPDATE', token: callback } };
}
if (state === 'UPDATE_AWAITING_PRICE' && text) {
  return { json: { route: 'SAVE_PRICE_ASK_COND_UPDATE', price: text } };
}
if (state === 'UPDATE_AWAITING_CONDITION' && callback) {
  return { json: { route: 'EXECUTE_UPDATE', condition: callback } };
}

// --- 6. DELETE FLOW (Dynamic) ---
if (state === 'DELETE_AWAITING_SELECTION' && callback) {
  return { json: { route: 'EXECUTE_DELETE', token: callback } };
}

// --- 7. ANALYZE FLOW (UPDATED FOR MULTI-SELECT) ---
if (state === 'ANALYZE_AWAITING_STOCK') {
  if (text) return { json: { route: 'SEARCH_STOCK_ANALYZE', query: text } };

  // NEW LOGIC: When stock is picked, don't execute immediately. Init the Cart.
  if (callback) return { json: { route: 'INIT_ANALYSIS_CART', token: callback } };
}

// NEW STATE: Loop for selecting Momentum, Trend, etc.
if (state === 'ANALYZE_SELECTING_OPTIONS') {
  if (callback === 'PROCEED_ANALYSIS') {
    return { json: { route: 'EXECUTE_ANALYZE_BATCH' } };
  }
  // If user clicks a specific option (MOMENTUM, TREND, etc)
  if (['MOMENTUM', 'TREND', 'VOLATILITY', 'CHARTS'].includes(callback)) {
    return { json: { route: 'ADD_SELECTION', selection: callback } };
  }
}
// NEW: AI Summary Logic
if (callback === 'AI_SUMMARY') {
   return { json: { route: 'EXECUTE_AI_SUMMARY' } };
}
// Default Fallback
return { json: { route: 'SHOW_MENU' } };

